'use strict';
const uid=()=>crypto.randomUUID?crypto.randomUUID():'id'+Date.now()+Math.random().toString(36).slice(2);
function migrate(input){const x=structuredClone(input);x.version=2;x.termEnd||='2027-01-22';x.teacher||='老師';x.termName||='115 上學期';x.sessions||=[];x.sources||=[];for(const c of x.classes){c.mode||=c.subject==='自然探究與實作'?'inquiry':'exam';c.target??=18;c.inquiryMethod||='target';}return x;}
validate=function(x){
 try{
 const str=(s,max=100)=>typeof s==='string'&&s.trim().length>0&&s.length<=max;
 const id=s=>typeof s==='string'&&/^[a-zA-Z0-9_-]{1,100}$/.test(s);
 if(!x||x.version!==2||!str(x.teacher)||!str(x.termName)||!validDate(x.termStart)||!validDate(x.termEnd)||x.termEnd<x.termStart||new Date(x.termEnd)-new Date(x.termStart)>370*86400000||!Array.isArray(x.classes)||(x.classes.length<1||x.classes.length>100)||!Array.isArray(x.exams)||x.exams.length!==3||!Array.isArray(x.events)||x.events.length>2000||!Array.isArray(x.sessions)||x.sessions.length>5000||!Array.isArray(x.sources)||!x.notes||typeof x.notes!=='object'||Array.isArray(x.notes))return false;
 const ids=x.classes.map(c=>c.id);if(new Set(ids).size!==ids.length||!ids.every(id))return false;
 if(!x.classes.every(c=>str(c.name)&&str(c.subject)&&['exam','inquiry'].includes(c.mode)&&Number.isInteger(c.target)&&c.target>=0&&c.target<=1000&&['target','scheduled'].includes(c.inquiryMethod)&&Array.isArray(c.slots)&&c.slots.length<=50&&c.slots.every(s=>Number.isInteger(s.day)&&s.day>=0&&s.day<=6&&validTime(s.time))&&new Set(c.slots.map(s=>s.day+s.time)).size===c.slots.length))return false;
 if(!x.exams.every((e,i)=>str(e.name)&&validDate(e.date)&&validDate(e.end)&&e.date<=e.end&&e.date>=x.termStart&&e.end<=x.termEnd&&(!i||e.date>x.exams[i-1].end)))return false;
 if(!x.events.every(e=>id(e.id)&&str(e.title)&&validDate(e.date)&&(!e.startTime&&!e.endTime||validTime(e.startTime)&&validTime(e.endTime)&&e.startTime<e.endTime)&&['off','extra'].includes(e.type)&&(e.classId==='all'||ids.includes(e.classId))&&(e.type!=='extra'||validTime(e.time)))||new Set(x.events.map(e=>e.id)).size!==x.events.length)return false;
 if(!x.sessions.every(s=>id(s.id)&&ids.includes(s.classId)&&validDate(s.date)&&s.date>=x.termStart&&s.date<=x.termEnd&&validTime(s.time)&&Number.isInteger(s.minutes)&&s.minutes>0&&s.minutes<=480&&typeof s.done==='boolean'&&typeof s.partner==='string'&&s.partner.length<=100&&typeof s.memo==='string'&&s.memo.length<=1000)||new Set(x.sessions.map(s=>s.id)).size!==x.sessions.length)return false;
 return Object.entries(x.notes).every(([k,n])=>k.length<200&&n&&typeof n.content==='string'&&n.content.length<=2000&&typeof n.homework==='string'&&n.homework.length<=1000&&validDate(n.date)&&ids.includes(n.classId)&&validTime(n.time))&&x.sources.every(s=>id(s.id)&&str(s.name,250)&&['schedule','calendar'].includes(s.kind));
 }catch{return false;}
};
let book;
try{book=CalendarStore.load();if(book&&(!Array.isArray(book.workspaces)||!book.workspaces.length||!book.workspaces.every(w=>typeof w.id==='string'&&validate(w.data))||!book.workspaces.some(w=>w.id===book.active)))throw Error('invalid');}catch{storageProblem=true;book=null;}
if(!book)book={version:2,active:'original',workspaces:[{id:'original',data:migrate(state)}]};
if(globalThis.TeacherPreset&&!book.workspaces.some(w=>w.id===TeacherPreset.id)){const preset=structuredClone(TeacherPreset);if(validate(preset.data)){book.workspaces.push(preset);book.active=preset.id;}}
if(globalThis.correctTeacherSchedule)book.workspaces.forEach(w=>correctTeacherSchedule(w));
state=book.workspaces.find(w=>w.id===book.active).data;
save=function(){try{book.workspaces.find(w=>w.id===book.active).data=state;CalendarStore.save(book);return true;}catch{toast('儲存失敗，請匯出備份保留資料。');return false;}};
lessons=(d,c='all',data=state,includeCancelled=false)=>CalendarEngine.lessons(d,c,data,includeCancelled);
remaining=(c,exam,data=state,at=taipeiNow())=>{const cl=data.classes.find(x=>x.id===c);if(cl.mode==='inquiry')return{...CalendarEngine.inquiry(c,data,at),excluded:0,extra:0};return CalendarEngine.remaining(c,data.exams.findIndex(e=>e.date===exam.date),data,at);};
const oldRender=render;
render=function(){
 oldRender();$('#profileLabel').textContent=`${state.teacher} · ${state.termName}`;
 $('#workspaceSelect').innerHTML=book.workspaces.map(w=>`<option value="${esc(w.id)}">${esc(w.data.teacher)} · ${esc(w.data.termName)}</option>`).join('');$('#workspaceSelect').value=book.active;
 const exam=state.exams[examIndex],period=CalendarEngine.period(state,examIndex);
 $('#countInfo').textContent=`${exam.name}區間：${period.start} ～ ${addDays(period.end,-1)}。剩餘堂數取此區間內尚未開始的課，並扣除假日及停課。自然探究與實作另計。`;
 $('#cards').innerHTML=state.classes.filter(c=>c.mode==='exam').map(c=>{const n=remaining(c.id,exam);return`<article class="card ${selectedClass===c.id?'selected':''}"><div class="row spread"><span class="class-name"><i class="dot"></i>${esc(c.name)}</span><span class="muted">${esc(c.subject)}</span></div><div class="count">${n.total}<small>堂課</small></div><div class="muted">${esc(exam.name)} · ${shortDate(n.start)}–${shortDate(addDays(n.end,-1))}</div><div class="card-bottom"><span>已排除 ${n.excluded} 堂停課</span><span>${n.extra?`含 ${n.extra} 堂補課`:`每週 ${c.slots.length} 堂`}</span></div><button class="card-button" data-class="${esc(c.id)}" aria-label="查看${esc(c.name)}的課程"></button></article>`}).join('')||'<p class="muted">尚無一般課程，請至課表設定新增班級。</p>';
 const inquiryClasses=state.classes.filter(c=>c.mode==='inquiry');
 $('#inquirySummary').innerHTML=inquiryClasses.length?`<h2>自然探究與實作 <small class="muted">獨立排課，不使用段考區間</small></h2><div class="inquiry-cards">${inquiryClasses.map(c=>{const n=CalendarEngine.inquiry(c.id,state,now);return`<div><b>${esc(c.name)}</b><p>剩餘 <strong>${c.targetConfigured===false&&c.inquiryMethod==='target'?'待設定':n.total}</strong>${c.targetConfigured===false&&c.inquiryMethod==='target'?'':' 堂'} <span class="muted">${c.inquiryMethod==='target'?(c.targetConfigured===false?'／請設定學期預定總堂數':'／學期目標 '+n.target+' 堂'):'／未來已排定課程'}</span></p><p class="muted">已完成 ${n.done} 堂 · ${n.minutes} 分鐘 · 未來已排 ${n.future} 堂${n.unconfirmed?' · '+n.unconfirmed+' 堂待確認':''}</p></div>`}).join('')}</div>`:'';$('#inquirySummary').classList.toggle('hidden',!inquiryClasses.length);
 // Calendar grid shows class names only; lesson time remains in daily detail.
 $$('#calendar .day .tag:not(.holiday):not(.exam)').forEach(el=>el.title=el.textContent);
};
const baseCollect=collectClass;
collectClass=function(){baseCollect();const c=draft.classes.find(c=>c.id===draftClass);c.mode=c.subject==='自然探究與實作'?'inquiry':$('#courseMode').value;};
const baseShow=showClass;
showClass=function(){baseShow();const c=draft.classes.find(c=>c.id===draftClass);$('#courseMode').value=c.mode;$('#scheduleRows').classList.toggle('hidden',c.mode==='inquiry');$('#addSlot').classList.toggle('hidden',c.mode==='inquiry');};
$('#courseMode').onchange=()=>{collectClass();showClass()};
$('#subjectName').onchange=()=>{if($('#subjectName').value.trim()==='自然探究與實作'){$('#courseMode').value='inquiry';collectClass();showClass();}};
$('#addClass').onclick=()=>{collectClass();const c={id:uid(),name:'新班級',subject:'物理',mode:'exam',target:18,inquiryMethod:'target',slots:[]};draft.classes.push(c);draftClass=c.id;$('#scheduleClass').innerHTML=draft.classes.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}／${esc(c.subject)}</option>`).join('');$('#scheduleClass').value=draftClass;showClass();};
// Name + subject uniquely identify a course in import workflows.
options=(all=true)=>(all?'<option value="all">全部班級</option>':'')+state.classes.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}／${esc(c.subject)}</option>`).join('');
const baseDetail=renderDetail;
renderDetail=function(){baseDetail();for(const l of lessons(selectedDate,filter).filter(l=>l.inquiry)){const button=$$('#detail [data-note]').find(b=>b.dataset.note===l.key);if(button){const el=document.createElement('p');el.className='help';el.textContent=`探究實作 · ${l.minutes} 分鐘 · ${l.done?'已完成':'未確認完成'}${l.partner?' · 換課老師：'+l.partner:''}${l.memo?' · '+l.memo:''}`;button.before(el);}}};

document.body.insertAdjacentHTML('beforeend',`
<dialog id="workspaceDialog"><div class="modal-head"><h2>新增老師／學期</h2><button class="close" data-close aria-label="關閉">×</button></div><form id="workspaceForm" class="modal-body"><p class="help">建立獨立資料區，不覆蓋其他老師或學期。這是本機分組，尚非登入帳號。</p><label class="field"><span>老師名稱</span><input name="teacher" maxlength="60" required></label><label class="field"><span>學期名稱</span><input name="termName" placeholder="例如：115 學年度下學期" maxlength="60" required></label><div class="form-grid"><label class="field"><span>開始日期</span><input name="start" type="date" required></label><label class="field"><span>結束日期</span><input name="end" type="date" required></label></div><p class="help">新學期先產生三次暫定段考日期；建立後請至設定調整。新學期不會自動帶入舊學期假日。</p><button class="btn primary" type="submit">建立工作區</button></form></dialog>
<dialog id="uploadDialog"><div class="modal-head"><h2>上傳行事曆與課表</h2><button class="close" data-close aria-label="關閉">×</button></div><div class="modal-body"><p class="muted" id="uploadWorkspace"></p><div class="upload-box"><h3>① 學校行事曆</h3><p class="help">包含假日、補假、運動會、三次段考。</p><input type="file" id="calendarUpload" aria-label="上傳學校行事曆" accept=".csv,.pdf,.png,.jpg,.jpeg,.webp"><button class="btn" data-template="calendar">下載行事曆 CSV 範本</button></div><div class="upload-box"><h3>② 老師課表</h3><p class="help">每列一堂固定課程；探究實作可留空星期及時間。</p><input type="file" id="scheduleUpload" aria-label="上傳老師課表" accept=".csv,.pdf,.png,.jpg,.jpeg,.webp"><button class="btn" data-template="schedule">下載課表 CSV 範本</button></div><p class="help">CSV（UTF-8）可預覽並套用；Excel 請另存 CSV。PDF／圖片可保存、預覽並在下方整理成課表／活動，目前未自動辨識文字；請校對後確認套用。檔案留在這台裝置，不傳送至外部服務。</p><section id="importPreview" aria-live="polite"></section><h3 class="section-title">本學期已上傳檔案</h3><div id="sourceList"></div><p class="help">JSON 備份包含設定與紀錄，不包含原始附件；請另行保存原檔。</p></div></dialog>
<dialog id="inquiryDialog"><div class="modal-head"><h2>自然探究與實作</h2><button class="close" data-close aria-label="關閉">×</button></div><div class="modal-body"><label class="field"><span>班級</span><select id="inquiryClass"></select></label><button class="btn" id="addInquiryClass">＋ 新增探究實作班級</button><form id="inquiryGoal"><div class="form-grid"><label class="field"><span>剩餘堂數算法</span><select id="inquiryMethod"><option value="target">學期目標 − 已確認完成堂數</option><option value="scheduled">未來已排定、尚未上課堂數</option></select></label><label class="field"><span>學期目標堂數</span><input id="inquiryTarget" type="number" min="0" max="1000" step="1" required></label></div><button class="btn" type="submit">儲存計算方式</button></form><h3 class="section-title">安排上課／與其他老師換課</h3><p class="help">每筆一堂，連堂請分別登記。日期過了不會自動標記完成；請確認實際授課後勾選。已排定的探究課以此紀錄為準，不自動套用一般課表或停課。</p><form id="sessionForm"><input name="id" type="hidden"><div class="form-grid"><label class="field"><span>上課日期</span><input name="date" type="date" required></label><label class="field"><span>開始時間</span><input name="time" type="time" value="09:10" required></label></div><div class="form-grid"><label class="field"><span>本堂時間（分鐘）</span><input name="minutes" type="number" min="1" max="480" step="1" value="50" required></label><label class="field"><span>換課老師（選填）</span><input name="partner" maxlength="100" placeholder="例如：王老師"></label></div><label class="field"><span>換課約定／備註</span><textarea name="memo" rows="2" maxlength="1000" placeholder="例如：交換高一 101 與 102 的探究課"></textarea></label><label class="field"><input name="done" type="checkbox"> 已確認完成這堂課</label><div class="row"><button class="btn primary" type="submit">儲存上課時間</button><button class="btn" type="button" id="cancelSessionEdit">清空表單</button></div></form><h3 class="section-title">已安排的課程</h3><div id="sessionList"></div></div></dialog>`);

function resetView(){filter='all';selectedClass=state.classes[0]?.id;examIndex=Math.max(0,state.exams.findIndex(e=>e.date>taipeiNow().date));selectedDate=taipeiNow().date;if(selectedDate<state.termStart||selectedDate>state.termEnd)selectedDate=state.termStart;month=selectedDate.slice(0,7);changeView(false);render();}
$('#workspaceSelect').onchange=e=>{const previous=book.active;if(!save()){e.target.value=previous;return;}book.active=e.target.value;state=book.workspaces.find(w=>w.id===book.active).data;save();resetView();};
$('#newWorkspace').onclick=()=>{$('#workspaceForm').reset();$('#workspaceDialog').showModal();};
$('#workspaceForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),start=f.get('start'),end=f.get('end'),teacher=f.get('teacher').trim(),termName=f.get('termName').trim();if(!validDate(start)||!validDate(end)||end<=start||!teacher||!termName){toast('請填寫有效的名稱及起訖日期。');return;}const days=Math.round((new Date(end)-new Date(start))/86400000);if(days<14||days>370){toast('學期長度請介於 14～370 天。');return;}const data=migrate(structuredClone(defaults));Object.assign(data,{teacher,termName,termStart:start,termEnd:end,events:[],notes:{},sessions:[],sources:[],classes:[{id:uid(),name:'新班級',subject:'物理',mode:'exam',target:18,inquiryMethod:'target',slots:[]}]});data.exams.forEach((ex,i)=>{ex.date=addDays(start,Math.floor(days*(i+1)/3)-2);ex.end=ex.date;});book.workspaces.push({id:uid(),data});book.active=book.workspaces.at(-1).id;state=data;const ok=save();$('#workspaceDialog').close();resetView();if(ok)toast('已建立獨立學期，請設定課表並確認段考日期。');};

let currentInquiry;
function inquiryOptions(){return state.classes.filter(c=>c.mode==='inquiry').map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('');}
function refreshInquiry(){const cs=state.classes.filter(c=>c.mode==='inquiry');$('#inquiryClass').innerHTML=inquiryOptions();if(!cs.some(c=>c.id===currentInquiry))currentInquiry=cs[0]?.id;$('#inquiryClass').value=currentInquiry||'';$('#inquiryGoal').classList.toggle('hidden',!currentInquiry);$('#sessionForm').classList.toggle('hidden',!currentInquiry);if(currentInquiry){const c=state.classes.find(c=>c.id===currentInquiry);$('#inquiryTarget').value=c.targetConfigured===false?'':c.target;$('#inquiryMethod').value=c.inquiryMethod;}$('#sessionList').innerHTML=state.sessions.filter(s=>s.classId===currentInquiry).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).map(s=>`<div class="event-manage"><div>${s.date} ${s.time} · ${s.minutes} 分鐘<br><span class="muted">${s.done?'✓ 已完成':'待確認'}${s.partner?' · '+esc(s.partner):''}</span><p>${esc(s.memo)}</p></div><div class="row"><button class="btn" data-session-edit="${s.id}">編輯</button><button class="btn" data-session-delete="${s.id}">刪除</button></div></div>`).join('')||'<p class="help">尚未安排課程。</p>';}
function clearSession(){$('#sessionForm').reset();$('#sessionForm').elements.id.value='';$('#sessionForm').elements.date.value=selectedDate;}
$('#openInquiry').onclick=()=>{refreshInquiry();clearSession();$('#inquiryDialog').showModal();};$('#inquiryClass').onchange=e=>{currentInquiry=e.target.value;refreshInquiry();clearSession();};$('#cancelSessionEdit').onclick=clearSession;
$('#addInquiryClass').onclick=()=>{const name=prompt('探究實作班級名稱，例如：高一 101');if(!name?.trim())return;const clean=name.trim().slice(0,100);let c=state.classes.find(c=>c.name===clean&&c.mode==='inquiry');if(!c){c={id:uid(),name:clean,subject:'自然探究與實作',mode:'inquiry',slots:[],target:18,inquiryMethod:'target'};state.classes.push(c);save();}currentInquiry=c.id;refreshInquiry();clearSession();render();};
$('#inquiryGoal').onsubmit=e=>{e.preventDefault();const c=state.classes.find(c=>c.id===currentInquiry);if(!c)return;c.target=Number($('#inquiryTarget').value);c.targetConfigured=true;c.inquiryMethod=$('#inquiryMethod').value;const ok=save();render();if(ok)toast('探究實作計算方式已更新。');};
$('#sessionForm').onsubmit=e=>{e.preventDefault();if(!currentInquiry)return;const f=new FormData(e.target),date=f.get('date'),time=f.get('time');if(!validDate(date)||date<state.termStart||date>state.termEnd||!validTime(time)){toast('上課日期必須在本學期內，時間需有效。');return;}const id=f.get('id')||uid(),minutes=Number(f.get('minutes')),done=f.get('done')==='on';if(!Number.isInteger(minutes)||minutes<1||minutes>480){toast('時間請填寫 1～480 分鐘。');return;}if(done&&(date>now.date||date===now.date&&time>now.time)){toast('未來課程不可標記為已完成。');return;}if(state.sessions.some(s=>s.id!==id&&s.classId===currentInquiry&&s.date===date&&s.time===time)){toast('此班級同一時間已安排課程，請編輯原紀錄。');return;}const s={id,classId:currentInquiry,date,time,minutes,partner:f.get('partner').trim(),memo:f.get('memo').trim(),done};state.sessions=state.sessions.filter(s=>s.id!==id);state.sessions.push(s);if(state.notes['inquiry_'+id])Object.assign(state.notes['inquiry_'+id],{date,time});const ok=save();clearSession();refreshInquiry();render();if(ok)toast('已記錄上課／換課時間。');};

let stagedImport=null;
let transcribing=null;
async function transcribeSource(id){
 try{const source=state.sources.find(s=>s.id===id),record=await CalendarStore.file('get',id);if(!source||!record?.file){toast('原始附件不在此裝置，請重新上傳。');return;}
 transcribing={id,kind:source.kind,file:record.file,workspace:book.active};stagedImport=null;
 const url=URL.createObjectURL(record.file),ext=source.name.split('.').at(-1).toLowerCase();
 $('#importPreview').innerHTML=`<h3>${esc(source.name)}</h3>${ext==='pdf'?`<iframe title="原始行事曆或課表 PDF" src="${url}" style="width:100%;height:360px"></iframe>`:['png','jpg','jpeg','webp'].includes(ext)?`<a href="${url}" target="_blank" rel="noopener"><img alt="原始課表或行事曆，點選放大" src="${url}" style="width:100%"></a>`:'<p class="help">CSV 原始檔可用下載按鈕取得。</p>'}<h3>依原始檔整理資料</h3><p class="help">下列是人工校對區，尚未自動辨識圖片。每列一堂課或一項活動，確認後才會計入。課表的同班同科會以這次填寫的完整課表取代。</p><div id="transcribeRows"></div><div class="row"><button class="btn" id="addTranscribeRow">＋ 新增一列</button><button class="btn primary" id="reviewTranscription">檢查整理結果</button></div><div id="transcribeResult"></div>`;
 $('#uploadDialog').addEventListener('close',()=>URL.revokeObjectURL(url),{once:true});addTranscribeRow();$('#transcribeRows').oninput=()=>{stagedImport=null;$('#transcribeResult').textContent='資料已更動，請重新檢查整理結果。';};$('#addTranscribeRow').onclick=addTranscribeRow;$('#reviewTranscription').onclick=reviewTranscription;
 }catch{toast('無法開啟原始檔。');}
}
function addTranscribeRow(){
 stagedImport=null;if($('#transcribeResult'))$('#transcribeResult').textContent='';const el=document.createElement('div');el.className='transcribe-row';
 el.innerHTML=transcribing.kind==='schedule'?`<label>班級<input data-col="班級" placeholder="高一 101"></label><label>科目<input data-col="科目" placeholder="物理／自然探究與實作"></label><label>星期<select data-col="星期"><option value="">探究不填</option>${[1,2,3,4,5,6,7].map(d=>`<option value="${d}">星期${week[d%7]}</option>`).join('')}</select></label><label>時間<input data-col="時間" type="time"></label><label>計算類型<select data-col="計算類型"><option>段考</option><option>探究</option></select></label><label>學期目標堂數<input data-col="學期目標堂數" type="number" min="0" max="1000" placeholder="探究課填寫"></label>`:`<label>日期<input data-col="日期" type="date"></label><label>結束日期（選填）<input data-col="結束日期" type="date"></label><label>名稱<input data-col="名稱" placeholder="運動會／國慶日補假"></label><label>類型<select data-col="類型"><option>停課</option><option>補課</option><option>段考1</option><option>段考2</option><option>段考3</option></select></label><label>班級<select data-col="班級"><option value="全部">全部</option>${[...new Set(state.classes.map(c=>c.name))].map(c=>`<option>${esc(c)}</option>`).join('')}</select></label><label>補課時間（補課必填）<input data-col="時間" type="time"></label>`;
 const remove=document.createElement('button');remove.className='btn';remove.textContent='移除此列';remove.onclick=()=>{el.remove();stagedImport=null;$('#transcribeResult').textContent='資料已更動，請重新檢查整理結果。';};el.append(remove);$('#transcribeRows').append(el);
}
function reviewTranscription(){
 try{if(!transcribing||transcribing.workspace!==book.active)return;const rows=$$('.transcribe-row').map(row=>Object.fromEntries([...row.querySelectorAll('[data-col]')].map(input=>[input.dataset.col,input.value])));if(!rows.length)throw Error('請至少整理一列');const quote=v=>'"'+String(v).replaceAll('"','""')+'"',text=[Object.keys(rows[0]),...rows.map(Object.values)].map(row=>row.map(quote).join(',')).join('\r\n');const parsed=parseImport(text,transcribing.kind);stagedImport={...parsed,kind:transcribing.kind,sourceId:transcribing.id,workspace:book.active};$('#transcribeResult').innerHTML=`<p class="help">${esc(parsed.message)}</p><button class="btn primary" id="applyImport">確認套用整理結果</button>`;$('#applyImport').onclick=applyImport;
 }catch(e){$('#transcribeResult').textContent=e.message;stagedImport=null;}
}
function download(name,text,type='text/csv;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const templates={schedule:'班級,科目,星期,時間,計算類型,學期目標堂數\r\n高一 101,物理,1,09:10,段考,\r\n高一 101,物理,3,10:10,段考,\r\n高一 101,自然探究與實作,,,探究,18\r\n',calendar:'日期,結束日期,名稱,類型,班級,時間\r\n2026-10-09,,國慶日補假,停課,全部,\r\n2026-10-14,2026-10-15,第一次段考,段考1,全部,\r\n2026-11-25,2026-11-26,第二次段考,段考2,全部,\r\n2027-01-13,2027-01-14,第三次段考,段考3,全部,\r\n2026-10-17,,週末補課,補課,全部,09:10\r\n'};
async function renderSources(){$('#sourceList').innerHTML=state.sources.map(s=>`<div class="event-manage"><span>${s.kind==='calendar'?'行事曆':'課表'} · ${esc(s.name)}<br><span class="muted">${s.applied?'已匯入資料':'原始檔，尚待整理'}</span></span><div class="row"><button class="btn" data-transcribe="${esc(s.id)}">預覽／整理</button><button class="btn" data-source="${esc(s.id)}">下載</button></div></div>`).join('')||'<p class="help">尚未上傳檔案。</p>';}
if($('#openUploads'))$('#openUploads').onclick=()=>{stagedImport=null;$('#importPreview').innerHTML='';$('#uploadWorkspace').textContent=`目前工作區：${state.teacher}／${state.termName}（${state.termStart}～${state.termEnd}）`;renderSources();$('#uploadDialog').showModal();};
function parseImport(text,kind){
 const rows=CalendarEngine.parseCSV(text);if(rows.length>2000)throw Error('最多可匯入 2,000 列');const next=structuredClone(state);let message='';
 if(kind==='schedule'){
  const required=['班級','科目','星期','時間'];if(!required.every(k=>k in rows[0]))throw Error('缺少欄位：班級、科目、星期、時間。請使用範本。');
  const groups=new Map();
  rows.forEach((r,i)=>{if(!r.班級||!r.科目)throw Error(`第 ${i+2} 列缺少班級或科目`);const key=r.班級+'\u0000'+r.科目;let c=groups.get(key);const mode=r.科目==='自然探究與實作'||r.計算類型==='探究'?'inquiry':'exam';if(r.計算類型&&!['探究','段考'].includes(r.計算類型))throw Error(`第 ${i+2} 列計算類型請填「探究」或「段考」`);if(!c){const existing=next.classes.find(c=>c.name===r.班級&&c.subject===r.科目);c=existing||{id:uid(),name:r.班級,subject:r.科目,target:18,inquiryMethod:'target'};c.mode=mode;c.slots=[];if(!existing)next.classes.push(c);groups.set(key,c);}if(c.mode!==mode)throw Error(`第 ${i+2} 列計算類型不一致`);if(r.學期目標堂數){c.target=Number(r.學期目標堂數);if(!Number.isInteger(c.target)||c.target<0||c.target>1000)throw Error(`第 ${i+2} 列目標堂數無效`);}if(mode==='exam'){if(!/^[1-7]$/.test(r.星期)||!validTime(r.時間))throw Error(`第 ${i+2} 列：星期需 1～7，時間需 HH:mm`);c.slots.push({day:Number(r.星期)%7,time:r.時間});}});
  message=`${groups.size} 個班級／科目、${rows.length} 列。相同班級＋科目的固定課表會被取代；其他課程與既有進度保留。新學期請先建立獨立工作區。`;
 }else{
  if(!['日期','名稱','類型'].every(k=>k in rows[0]))throw Error('缺少欄位：日期、名稱、類型。請使用範本。');
  const seenExams=new Set();let count=0;
  rows.forEach((r,i)=>{const end=r.結束日期||r.日期;if(!validDate(r.日期)||!validDate(end)||end<r.日期||r.日期<next.termStart||end>next.termEnd||!r.名稱)throw Error(`第 ${i+2} 列日期需在本學期內且名稱不可空白`);
   if(/^段考[123]$/.test(r.類型)){const index=Number(r.類型.at(-1))-1;if(seenExams.has(index))throw Error('同次段考不可重複');seenExams.add(index);next.exams[index]={name:r.名稱,date:r.日期,end};return;}
   const type=r.類型==='停課'?'off':r.類型==='補課'?'extra':null;if(!type)throw Error(`第 ${i+2} 列類型應為停課、補課、段考1、段考2或段考3`);if(type==='extra'&&!validTime(r.時間))throw Error(`第 ${i+2} 列補課需要 HH:mm 時間`);
   const matches=!r.班級||r.班級==='全部'?['all']:next.classes.filter(c=>c.name===r.班級).map(c=>c.id);if(!matches.length)throw Error(`找不到班級「${r.班級}」，請先匯入課表`);
   for(let d=r.日期;d<=end;d=addDays(d,1))for(const classId of matches){if(!next.events.some(e=>e.date===d&&e.title===r.名稱&&e.type===type&&e.classId===classId&&(type==='off'||e.time===r.時間))){next.events.push({id:uid(),date:d,title:r.名稱,type,classId,time:r.時間||''});count++;}}
  });message=`新增 ${count} 筆活動，更新 ${seenExams.size} 次段考。相同活動不重複匯入；原有活動保留。`;
 }
 if(!validate(next))throw Error('資料未通過檢查：確認段考先後、日期範圍、名稱長度及重複課表。');
 return{next,message,rows};
}
async function upload(file,kind){
 if(!file)return;const workspace=book.active;$('#importPreview').textContent='讀取檔案中…';stagedImport=null;
 try{if(file.size>20*1024*1024)throw Error('檔案上限為 20 MB');const ext=file.name.split('.').at(-1).toLowerCase();if(!['csv','pdf','png','jpg','jpeg','webp'].includes(ext))throw Error('請選擇 CSV、PDF 或圖片；Excel 請另存 UTF-8 CSV。');
  if(ext==='csv'){const parsed=parseImport(await file.text(),kind);stagedImport={...parsed,file,kind,workspace};$('#importPreview').innerHTML=`<h3>確認匯入 ${esc(file.name)}</h3><p>${esc(parsed.message)}</p><div class="import-table"><table><thead><tr>${Object.keys(parsed.rows[0]).map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${parsed.rows.slice(0,20).map(r=>`<tr>${Object.values(r).map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="help">顯示前 20 列，全部 ${parsed.rows.length} 列將套用。</p><button class="btn primary" id="applyImport">確認匯入並重算</button>`;$('#applyImport').onclick=applyImport;}
  else{const id=uid();await CalendarStore.file('put',{id,workspace,file});if(book.active!==workspace)throw Error('工作區已切換，請重新上傳');state.sources.push({id,name:file.name,kind,applied:false});const ok=save();renderSources();const url=URL.createObjectURL(file);$('#importPreview').innerHTML=`<p>原始檔已保存；尚未自動辨識。請依預覽於設定輸入課表／活動。</p>${ext==='pdf'?`<iframe title="上傳 PDF 預覽" src="${url}" style="width:100%;height:320px"></iframe>`:`<img alt="上傳原始檔預覽" src="${url}" style="max-width:100%">`}`;$('#uploadDialog').addEventListener('close',()=>URL.revokeObjectURL(url),{once:true});if(ok){toast('原始檔已保存在此學期。');await transcribeSource(id);}}
 }catch(err){$('#importPreview').textContent=err.message||'讀取或儲存失敗，原有資料未變更。';}
}
async function applyImport(){const staged=stagedImport;if(!staged||book.active!==staged.workspace)return;const button=$('#applyImport');button.disabled=true;try{if(staged.sourceId){staged.next.sources.find(s=>s.id===staged.sourceId).applied=true;}else{const id=uid();await CalendarStore.file('put',{id,workspace:book.active,file:staged.file});staged.next.sources.push({id,name:staged.file.name,kind:staged.kind,applied:true});}const prior=state;state=staged.next;if(!save()){state=prior;book.workspaces.find(w=>w.id===book.active).data=prior;throw Error('無法儲存匯入資料，請先匯出備份。');}stagedImport=null;$('#importPreview').textContent='已匯入，課表與堂數已更新。';renderSources();render();}catch(e){$('#importPreview').textContent=e.message;}}
$('#calendarUpload').onchange=e=>{upload(e.target.files[0],'calendar');e.target.value='';};$('#scheduleUpload').onchange=e=>{upload(e.target.files[0],'schedule');e.target.value='';};
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.transcribe)await transcribeSource(d.transcribe);if(d.template)download(d.template==='calendar'?'行事曆範本.csv':'課表範本.csv','\uFEFF'+templates[d.template]);if(d.source){try{const record=await CalendarStore.file('get',d.source);if(!record?.file){toast('此裝置沒有原始附件，請重新上傳。');return;}const url=URL.createObjectURL(record.file);const a=document.createElement('a');a.href=url;a.download=record.file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}catch{toast('無法讀取附件。');}}if(d.sessionEdit){const s=state.sessions.find(s=>s.id===d.sessionEdit);for(const key of ['id','date','time','minutes','partner','memo'])$('#sessionForm').elements[key].value=s[key];$('#sessionForm').elements.done.checked=s.done;}if(d.sessionDelete&&confirm('刪除此排課紀錄？對應上課進度仍保留在進度紀錄。')){state.sessions=state.sessions.filter(s=>s.id!==d.sessionDelete);save();refreshInquiry();render();}});
// Restore is non-destructive: add a separate workspace, migrate v1 backups.
$('#backupFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5000000)throw Error();const raw=JSON.parse(await file.text()),data=raw.version===1?migrate(raw):raw;if(!validate(data))throw Error();const id=uid();data.termName+='（還原）';book.workspaces.push({id,data});book.active=id;state=data;const ok=save();$('#settingsDialog').close();resetView();if(ok)toast('備份已還原為獨立工作區，原資料保留。');}catch{toast('備份格式或資料無效，原工作區未更動。');}finally{e.target.value='';}};
$('#importData').textContent='還原為另一工作區';
// Keep event targeting unambiguous: inquiry courses are scheduled in their own editor.
const originalOpenEvent=openEvent;
openEvent=function(){originalOpenEvent();$('#eventClass').innerHTML='<option value="all">全部一般課程</option>'+state.classes.filter(c=>c.mode==='exam').map(c=>`<option value="${esc(c.id)}">${esc(c.name)}／${esc(c.subject)}</option>`).join('');};$('#addEvent').onclick=openEvent;
setInterval(()=>render(),60000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)render();});
render();$('#uploadDialog')?.remove();if(storageProblem)toast('部分舊資料無法讀取，請保留原備份並還原。');else save();

// Enable offline shell after HTTPS deployment. Local development stays uncached.
if(location.protocol==='https:'&&'serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>toast('離線模式無法啟用，線上功能仍可使用。'));
